def _retryable_positions(record: _TaskRecord) -> List[int]:
    """按规则计算待复核项在该任务自身 ``items`` 中的位置，顺序去重。

    completed 只选已有失败项；failed 额外从错误项下标起纳入错误项及其
    后尚无结果的项（错误项下标已在已有结果范围内时只起去重作用）。
    """
    candidates = {
        result.index
        for result in record.results
        if result.status == ITEM_FAILED
    }
    if record.status == TASK_FAILED:
        error_index = record.error.index if record.error else None
        if isinstance(error_index, int) and error_index < record.total:
            candidates.update(range(error_index, record.total))
    # 已有结果中的通过项绝不复核（range 可能在错误下标早于首个无结果
    # 项时把它们带入，这里显式剔除）。
    passed = {
        result.index
        for result in record.results
        if result.status == ITEM_PASSED
    }
    candidates.difference_update(passed)
    return sorted(candidates)

