from zk_batch import VerificationTaskQueue, ZKVerifier, VerificationInfrastructureError

def mat(pid, proto="g"):
    return {"proof_id": pid, "protocol": proto, "circuit_id": "c",
            "aggregation_key": "k", "public_inputs": ["SECRET-x"], "proof": "SECRET-y"}
def item(i, m=None): return {"item_id": i, "proof": m or mat(i)}

class V(ZKVerifier):
    protocol = "g"
    def __init__(self, reject=(), boom=()): self.r, self.b, self.seen = set(reject), set(boom), []
    def verify(self, p):
        self.seen.append(p.proof_id)
        if p.proof_id in self.b: raise RuntimeError("boom "+p.proof_id)
        return p.proof_id not in self.r

# failed mid-batch -> retry error item + tail; then chain
q = VerificationTaskQueue()
t = q.submit([item("p1"),item("p2"),item("p3"),item("p4")], verifiers=V(reject={"p1"}, boom={"p2"})).task_id
try: q.run_next()
except VerificationInfrastructureError as e: print("src error idx:", e.index)
rc = q.retry_failed(t)
print("retry1:", rc.summary.item_ids, rc.retried_indexes, rc.status, list(rc.to_dict()))
try: q.run_task(rc.task_id)   # inherits broken verifiers -> fails at p2 again
except VerificationInfrastructureError as e: print("retry error idx:", e.index)
print("partial:", [r.item_id for r in q.result(rc.task_id).results])
rc2 = q.retry_failed(rc.task_id, verifiers=V())
r2 = q.run_task(rc2.task_id)
print("retry2 fixed:", [(x.index, x.item_id, x.status) for x in r2.results], "seen:", q._tasks[rc2.task_id].verifiers.seen)
print("source still failed:", q.status(t), [x.item_id for x in q.result(t).results], q.task_error(t).index)

# distinct ids, stable order
a = q.retry_failed(rc.task_id, verifiers=V()); b = q.retry_failed(rc.task_id, verifiers=V())
print("distinct:", a.task_id != b.task_id, a.retried_indexes == b.retried_indexes)
